    TimekeepingOwnership.ensure_initial!
    timekeeping = TimekeepingHandoffFakes::InMemoryTimekeepingStore.new
    owners = TimekeepingHandoffFakes.owners(timekeeping:, settle: nil, relay: false)

    Dir.mktmpdir do |report_root|
